#include <bits/stdc++.h>
using namespace std;

struct UnionFind {
    vector<int> parent, rank;
    void build(int n) {
        parent.resize(n);
        rank.resize(n);
        for (int i = 0; i < n; ++i) {
            parent[i] = i;
            rank[i] = 0;
        }
    }
    int find_set(int x) {
        if (parent[x] != x) parent[x] = find_set(parent[x]);
        return parent[x];
    }
    void merge(int a, int b) {
        a = find_set(a);
        b = find_set(b);
        if (a != b) {
            if (rank[a] < rank[b]) swap(a, b);
            parent[b] = a;
            if (rank[a] == rank[b]) rank[a]++;
        }
    }
};

long long power_mod(long long base, int exp, int mod) {
    long long res = 1;
    for (; exp > 0; exp >>= 1) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    const int MOD = 1e9 + 7;
    if (k == 0) {
        cout << power_mod(n, n - 1, MOD) << "\n";
        return 0;
    }
    UnionFind uf;
    uf.build(n);
    for (int i = 0; i < n; ++i) {
        uf.merge(i, (long long)i * k % n);
    }
    long long result = 1;
    for (int i = 0; i < n; ++i) {
        if (uf.find_set(i) != i) continue;
        long long t = power_mod(k, uf.rank[uf.find_set(i)], n);
        if (t == 1) {
            result = (result * n) % MOD;
        }
    }
    cout << result << "\n";
}
